                queue = [(r,c)]
                visited.add((r,c))

                while queue:
                    curr_r, curr_c = queue.pop(0)
                    component.append((curr_r, curr_c))

                    neighbors = [
                        (curr_r-1, curr_c), (curr_r+1, curr_c),
                        (curr_r, curr_c-1), (curr_r, curr_c+1)
                    ]
                    for nr, nc in neighbors:
