from collections import deque

rows_d, cols_d = len(demo_input), len(demo_input[0])
background = 3

def find_all_components(grid, bg):
    visited = set()
    all_comps = {}
    for r in range(rows_d):
        for c in range(cols_d):
            color = grid[r][c]
            if color != bg and (r, c) not in visited:
                cells = []
                visited.add((r, c))
                cells.append((r, c))
                q = deque()
                q.append((r, c))
                while q:
                    cr, cc = q.popleft()
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows_d and 0 <= nc < cols_d:
                            if grid[nr][nc] == color and (nr, nc) not in visited:
                                visited.add((nr, nc))
                                cells.append((nr, nc))
                                q.append((nr, nc))
                rmin = min(cr for cr, cc in cells)
                rmax = max(cr for cr, cc in cells)
                cmin = min(cc for cr, cc in cells)
                cmax = max(cc for cr, cc in cells)
                if color not in all_comps:
                    all_comps[color] = []
                all_comps[color].append((rmin, rmax, cmin, cmax))
    return all_comps

