def bbox_fill(grid, bg):
    r, c = len(grid), len(grid[0])
    output = [[bg]*c for _ in range(r)]
    visited = set()
    all_comps = {}

    for rr in range(r):
        for cc in range(c):
            color = grid[rr][cc]
            if color != bg and (rr, cc) not in visited:
                cells = [(rr,cc)]
                visited.add((rr,cc))
                q = deque([(rr,cc)])
                while q:
                    cr, cc_ = q.popleft()
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
