                rmin, rmax, cmin, cmax = min(x for x,y in cells), max(x for x,y in cells), min(y for x,y in cells), max(y for x,y in cells)
                while len(cells) > 0:
                    all_comps.setdefault(color, []).append((rmin, rmax, cmin, cmax))

    for color in sorted(all_comps.keys()):
        for rmin, rmax, cmin, cmax in all_comps[color]:
